import test from 'node:test';
import assert from 'node:assert/strict';
import { exportCsv } from '../src/export.js';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { recordPayment, balanceDue } from '../src/payments.js';

test('exportCsv returns header and ends with newline', () => {
  const result = exportCsv([]);
  assert.equal(result, 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due\n');
});

test('exportCsv includes header', () => {
  const result = exportCsv([]);
  assert.ok(result.includes('number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due'));
});

test('exportCsv exports single invoice', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  assert.equal(lines.length, 3);
  assert.ok(lines[1].includes('INV-2025-0001'));
  assert.ok(lines[1].includes('Northwind Studio'));
});

test('exportCsv includes all required fields', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  const dataLine = lines[1];

  const fields = dataLine.split(',');
  assert.equal(fields.length, 10);
  assert.equal(fields[0], 'INV-2025-0001');
  assert.equal(fields[1], 'Northwind Studio');
  assert.equal(fields[2], '2025-10-07');
  assert.equal(fields[3], '2025-11-06');
  assert.equal(fields[4], 'issued');
});

test('exportCsv formats amounts in euros with 2 decimals', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  const dataLine = lines[1];

  const fields = dataLine.split(',');
  assert.ok(/^\d+\.\d{2}$/.test(fields[5]));
  assert.ok(/^\d+\.\d{2}$/.test(fields[6]));
  assert.ok(/^\d+\.\d{2}$/.test(fields[7]));
  assert.ok(/^\d+\.\d{2}$/.test(fields[8]));
  assert.ok(/^\d+\.\d{2}$/.test(fields[9]));
});

test('exportCsv exports multiple invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-08',
    lines: [{ sku: 'DEV-HOUR', qty: 3 }],
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2025-0001']).value;

  const result = exportCsv([issued1, issued2]);
  const lines = result.split('\n');
  assert.equal(lines.length, 4);
  assert.ok(lines[1].includes('INV-2025-0001'));
  assert.ok(lines[2].includes('INV-2025-0002'));
});

test('exportCsv handles customer names with comma', () => {
  const inv = createInvoice({
    customerId: 'C-006',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);
  assert.ok(result.includes('"Marlow "The Print Shop""'));
});

test('exportCsv handles customer names with quotes', () => {
  const inv = createInvoice({
    customerId: 'C-006',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  const dataLine = lines[1];
  const fields = dataLine.split(',');
  assert.equal(fields[1], '"Marlow "The Print Shop""');
});

test('exportCsv includes draft invoices', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const result = exportCsv([draft]);
  const lines = result.split('\n');
  assert.equal(lines.length, 3);
  assert.ok(lines[1].includes('draft'));
  assert.ok(lines[1].includes(''));
});

test('exportCsv with partially paid invoice', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);
  const partialPaid = recordPayment(issued, { amount: 2000, date: '2025-10-08' }).value;

  const result = exportCsv([partialPaid]);
  const lines = result.split('\n');
  const dataLine = lines[1];

  const fields = dataLine.split(',');
  assert.equal(fields[4], 'partially_paid');
  const due = parseFloat(fields[9]);
  const expectedDue = (totals.total - 2000) / 100;
  assert.equal(due, expectedDue);
});

test('exportCsv with fully paid invoice', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);
  const paid = recordPayment(issued, { amount: totals.total, date: '2025-10-08' }).value;

  const result = exportCsv([paid]);
  const lines = result.split('\n');
  const dataLine = lines[1];

  const fields = dataLine.split(',');
  assert.equal(fields[4], 'paid');
  assert.equal(fields[9], '0.00');
});

test('exportCsv lines end with newline', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);
  assert.ok(result.endsWith('\n'));
});

test('exportCsv separates lines with newline', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-08',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2025-0001']).value;

  const result = exportCsv([issued1, issued2]);
  const lines = result.split('\n');
  assert.equal(lines.length, 4);
  assert.equal(lines[3], '');
});

test('exportCsv with empty invoice number (draft)', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const result = exportCsv([draft]);
  const lines = result.split('\n');
  const dataLine = lines[1];

  const fields = dataLine.split(',');
  assert.equal(fields[0], '');
});

test('exportCsv amounts exclude currency sign', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);
  assert.ok(!result.includes('€'));
});

test('exportCsv amounts exclude thousands separator', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'BRAND-BOOK', qty: 10 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);
  assert.ok(!result.includes(',000'));
});

test('exportCsv with small amounts', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'STICKER', qty: 10 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  const dataLine = lines[1];

  const fields = dataLine.split(',');
  assert.ok(/^0\.\d{2}$/.test(fields[5]));
});

test('exportCsv with large amounts', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'BRAND-BOOK', qty: 10 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  const dataLine = lines[1];

  const fields = dataLine.split(',');
  const subtotal = parseFloat(fields[5]);
  assert.ok(subtotal > 2000);
});

test('exportCsv preserves invoice order', () => {
  const invoices = [];
  for (let i = 1; i <= 5; i++) {
    const inv = createInvoice({
      customerId: 'C-001',
      issueDate: `2025-10-${String(i).padStart(2, '0')}`,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;
    const existing = invoices.map((x) => x.number).filter((n) => n);
    invoices.push(issueInvoice(inv, existing).value);
  }

  const result = exportCsv(invoices);
  const lines = result.split('\n');
  for (let i = 0; i < 5; i++) {
    assert.ok(lines[i + 1].includes(`INV-2025-000${i + 1}`));
  }
});

test('exportCsv calculates totals correctly', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  }).value;
  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  const dataLine = lines[1];

  const fields = dataLine.split(',');
  assert.equal(parseFloat(fields[5]), totals.subtotal / 100);
  assert.equal(parseFloat(fields[6]), totals.discount / 100);
  assert.equal(parseFloat(fields[7]), totals.vat / 100);
  assert.equal(parseFloat(fields[8]), totals.total / 100);
});

test('exportCsv with discounts', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  const dataLine = lines[1];

  const fields = dataLine.split(',');
  const discount = parseFloat(fields[6]);
  assert.ok(discount > 0);
});

test('exportCsv with VAT', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  const dataLine = lines[1];

  const fields = dataLine.split(',');
  const vat = parseFloat(fields[7]);
  assert.ok(vat > 0);
});

test('exportCsv with zero-VAT items', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  const dataLine = lines[1];

  const fields = dataLine.split(',');
  assert.equal(fields[7], '0.00');
});

test('exportCsv header is always first line', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
});

test('exportCsv with mixed statuses', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-08',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([draft, issued]);
  const lines = result.split('\n');
  assert.ok(lines[1].includes('draft'));
  assert.ok(lines[2].includes('issued'));
});

test('exportCsv with special characters in customer name', () => {
  const inv = createInvoice({
    customerId: 'C-004',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);
  assert.ok(result.includes('Smith, Jones & Partners'));
});

test('exportCsv properly escapes CSV special characters', () => {
  const inv = createInvoice({
    customerId: 'C-006',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);
  const lines = result.split('\n');
  const dataLine = lines[1];

  const fields = dataLine.split(',');
  assert.ok(fields[1].startsWith('"'));
  assert.ok(fields[1].endsWith('"'));
});

test('exportCsv with many invoices', () => {
  const invoices = [];
  for (let i = 0; i < 100; i++) {
    const inv = createInvoice({
      customerId: 'C-001',
      issueDate: `2025-10-${String((i % 30) + 1).padStart(2, '0')}`,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;
    const existing = invoices.map((x) => x.number).filter((n) => n);
    invoices.push(issueInvoice(inv, existing).value);
  }

  const result = exportCsv(invoices);
  const lines = result.split('\n');
  assert.equal(lines.length, 102);
});

